# (cur, country, id, display name, freq, abdv_category, plihal_sector, [raw member names])
# freq: Q quarterly, M monthly, P policy meeting, W weekly
# abdv categories: Real Activity, Consumption, Investment, Government, Net Exports, Prices, Forward-Looking, Monetary
F = []
def f(cur, ctry, fid, name, freq, cat, sec, members):
    F.append(dict(cur=cur, country=ctry, fid=fid, name=name, freq=freq, cat=cat, sector=sec, members=members))

